package leasekv

import (
	"slices"
	"time"

	"github.com/hmdsefi/faultline"
	"github.com/hmdsefi/faultline/kernel"
)

// Server serves clients while it holds the lease. It asks the lock for the lease every
// RenewEvery. A grant is valid until the time the server sent the request plus the TTL. On a new
// epoch the server loads the store's data into its cache before it serves. Appends go to the
// store; the server adds the value to its cache and acknowledges the append as it sends it. Gets
// are answered from the cache.
type Server struct {
	W          *faultline.World
	Lock       kernel.NodeID
	Store      kernel.NodeID
	RenewEvery time.Duration

	epoch  uint64
	until  time.Time // the lease is valid before until
	ready  bool      // the cache holds the store's data for epoch
	holder string    // the holder the lock named last
	cache  map[string][]string
}

// Boot starts the server with an empty cache and no lease.
func (s *Server) Boot(n *kernel.Node) {
	s.epoch, s.until, s.ready, s.holder = 0, time.Time{}, false, ""
	s.cache = map[string][]string{}
	s.W.Net.Handle(n, func(from kernel.NodeID, msg any) { s.handle(n, from, msg) })
	var renew func()
	renew = func() {
		s.W.Net.Send(n, s.Lock, Acquire{Sent: n.Now()})
		if s.epoch > 0 && !s.ready && n.Now().Before(s.until) {
			s.W.Net.Send(n, s.Store, Sync{Epoch: s.epoch})
		}
		n.After(s.RenewEvery, "renew", renew)
	}
	n.After(kernel.Uniform(n.Rand(), 0, s.RenewEvery), "renew", renew)
}

func (s *Server) handle(n *kernel.Node, from kernel.NodeID, msg any) {
	switch m := msg.(type) {
	case Grant:
		s.granted(n, m)
	case Busy:
		s.holder = m.Holder
	case SyncOK:
		if m.Epoch == s.epoch && !s.ready {
			s.cache, s.ready = m.Data, true
		}
	case Fenced:
		s.fenced(m)
	case Written:
		s.written(m)
	case Append:
		s.append(n, from, m)
	case Get:
		if !s.serving(n) {
			s.W.Net.Send(n, from, NotLeader{Seq: m.Seq, Hint: s.hint(n)})
			return
		}
		s.W.Net.Send(n, from, GetOK{Seq: m.Seq, List: slices.Clone(s.cache[m.Key])})
	}
}

// serving reports whether the server holds a valid lease and has loaded the store's data.
func (s *Server) serving(n *kernel.Node) bool {
	return s.ready && n.Now().Before(s.until)
}

func (s *Server) granted(n *kernel.Node, m Grant) {
	if m.Epoch < s.epoch {
		return
	}
	until := m.Sent.Add(m.TTL)
	if m.Epoch > s.epoch {
		s.epoch, s.ready, s.until = m.Epoch, false, until
		s.cache = map[string][]string{}
		s.W.Net.Send(n, s.Store, Sync{Epoch: m.Epoch})
	}
	if until.After(s.until) {
		s.until = until
	}
	s.holder = n.Name()
}

// fenced steps down: a newer epoch exists.
func (s *Server) fenced(m Fenced) {
	if m.Epoch == s.epoch {
		s.ready, s.until = false, time.Time{}
	}
}

func (s *Server) append(n *kernel.Node, from kernel.NodeID, m Append) {
	if !s.serving(n) {
		s.W.Net.Send(n, from, NotLeader{Seq: m.Seq, Hint: s.hint(n)})
		return
	}
	client := n.Sim().Node(from).Name()
	s.W.Net.Send(n, s.Store, Write{Epoch: s.epoch, Client: client, Seq: m.Seq, Key: m.Key, Value: m.Value})
	s.cache[m.Key] = append(s.cache[m.Key], m.Value)
	s.W.Net.Send(n, from, AppendOK{Seq: m.Seq})
}

// written updates the cache with the store's list.
func (s *Server) written(m Written) {
	if len(m.List) > len(s.cache[m.Key]) {
		s.cache[m.Key] = m.List
	}
}

// hint names the holder the lock named last, if that is another server.
func (s *Server) hint(n *kernel.Node) string {
	if s.holder == n.Name() {
		return ""
	}
	return s.holder
}
package leasekv

import (
	"bytes"
	"encoding/json"
	"errors"
	"io/fs"
	"maps"
	"slices"

	"github.com/hmdsefi/faultline"
	"github.com/hmdsefi/faultline/kernel"
	"github.com/hmdsefi/faultline/kernel/simdisk"
)

const walPath = "/wal"

// Store keeps the list of every key in a write-ahead log on its volume. It syncs the log before
// every reply, so a reply only describes durable state. It remembers the last write of every
// client in the same log, so a write sent again is applied once. It rejects requests whose epoch
// is below the highest epoch it has seen.
type Store struct {
	W *faultline.World

	data  map[string][]string
	last  map[string]uint64 // per client: Seq of its last applied write
	fence uint64
	wal   *simdisk.File
}

// record is one line of the write-ahead log: a write, or only an epoch when Key is empty.
type record struct {
	Epoch  uint64 `json:"epoch"`
	Client string `json:"client,omitempty"`
	Seq    uint64 `json:"seq,omitempty"`
	Key    string `json:"key,omitempty"`
	Value  string `json:"value,omitempty"`
}

// Boot rebuilds the store from its log and starts serving.
func (s *Store) Boot(n *kernel.Node) {
	s.data, s.last, s.fence = map[string][]string{}, map[string]uint64{}, 0
	wal, err := s.recover(s.W.Disk.Volume(n))
	if err != nil {
		n.Sim().Fail(err)
		return
	}
	s.wal = wal
	s.W.Net.Handle(n, func(from kernel.NodeID, msg any) {
		switch m := msg.(type) {
		case Sync:
			s.sync(n, from, m)
		case Write:
			s.write(n, from, m)
		}
	})
}

// List returns a copy of the list of key.
func (s *Store) List(key string) []string { return slices.Clone(s.data[key]) }

func (s *Store) sync(n *kernel.Node, from kernel.NodeID, m Sync) {
	if m.Epoch < s.fence {
		s.W.Net.Send(n, from, Fenced{Epoch: m.Epoch, Fence: s.fence})
		return
	}
	if m.Epoch > s.fence {
		if err := s.log(record{Epoch: m.Epoch}); err != nil {
			return
		}
	}
	data := maps.Clone(s.data)
	for k, v := range data {
		data[k] = slices.Clone(v)
	}
	s.W.Net.Send(n, from, SyncOK{Epoch: m.Epoch, Data: data})
}

func (s *Store) write(n *kernel.Node, from kernel.NodeID, m Write) {
	if m.Epoch < s.fence {
		s.W.Net.Send(n, from, Fenced{Epoch: m.Epoch, Fence: s.fence})
		return
	}
	if m.Seq > s.last[m.Client] {
		r := record{Epoch: m.Epoch, Client: m.Client, Seq: m.Seq, Key: m.Key, Value: m.Value}
		if err := s.log(r); err != nil {
			return
		}
	}
	s.W.Net.Send(n, from, Written{Client: m.Client, Seq: m.Seq, Key: m.Key, List: slices.Clone(s.data[m.Key])})
}

// log appends r to the log, syncs it, and applies it.
func (s *Store) log(r record) error {
	line, err := json.Marshal(r)
	if err != nil {
		return err
	}
	if _, err := s.wal.Append(append(line, '\n')); err != nil {
		return err
	}
	if err := s.wal.Sync(); err != nil {
		return err
	}
	s.apply(r)
	return nil
}

func (s *Store) apply(r record) {
	s.fence = max(s.fence, r.Epoch)
	if r.Key != "" {
		s.data[r.Key] = append(s.data[r.Key], r.Value)
		s.last[r.Client] = r.Seq
	}
}

// recover replays the log and returns it open for appends.
func (s *Store) recover(vol *simdisk.Volume) (*simdisk.File, error) {
	log, err := vol.ReadFile(walPath)
	if errors.Is(err, fs.ErrNotExist) {
		f, err := vol.Create(walPath)
		if err != nil {
			return nil, err
		}
		return f, vol.SyncDir("/")
	}
	if err != nil {
		return nil, err
	}
	for line := range bytes.Lines(log) {
		var r record
		if err := json.Unmarshal(line, &r); err != nil {
			return nil, err
		}
		s.apply(r)
	}
	return vol.Open(walPath)
}
package leasekv

import (
	"time"

	"github.com/hmdsefi/faultline"
	"github.com/hmdsefi/faultline/kernel"
)

// Lock grants the lease. The holder renews it. Another server gets it only after it expired on
// the lock's clock, and each new holder gets the next epoch.
type Lock struct {
	W   *faultline.World
	TTL time.Duration

	holder string
	epoch  uint64
	expiry time.Time
}

// Boot starts the lock.
func (l *Lock) Boot(n *kernel.Node) {
	l.holder, l.epoch, l.expiry = "", 0, time.Time{}
	l.W.Net.Handle(n, func(from kernel.NodeID, msg any) {
		req, ok := msg.(Acquire)
		if !ok {
			return
		}
		name, now := n.Sim().Node(from).Name(), n.Now()
		held := now.Before(l.expiry)
		if held && l.holder != name {
			l.W.Net.Send(n, from, Busy{Holder: l.holder})
			return
		}
		if !held {
			l.holder = name
			l.epoch++
		}
		l.expiry = now.Add(l.TTL)
		l.W.Net.Send(n, from, Grant{Epoch: l.epoch, TTL: l.TTL, Sent: req.Sent})
	})
}
package leasekv

import (
	"strconv"
	"time"
)

// The messages between the nodes.
type (
	// Acquire asks the lock for the lease, or renews it for the holder. Sent is the server's
	// clock when it sent the request.
	Acquire struct{ Sent time.Time }
	// Grant gives the lease to the server that sent the Acquire: epoch Epoch, valid for TTL from
	// the Acquire's Sent.
	Grant struct {
		Epoch uint64
		TTL   time.Duration
		Sent  time.Time
	}
	// Busy tells a server that Holder has the lease.
	Busy struct{ Holder string }
	// Sync asks the store for all its data. It raises the store's fence to Epoch.
	Sync struct{ Epoch uint64 }
	// SyncOK carries the store's data at the time it handled the Sync of Epoch.
	SyncOK struct {
		Epoch uint64
		Data  map[string][]string
	}
	// Write asks the store to append Value to Key for request Seq of Client.
	Write struct {
		Epoch      uint64
		Client     string
		Seq        uint64
		Key, Value string
	}
	// Written confirms request Seq of Client. List is the key's list after the write.
	Written struct {
		Client string
		Seq    uint64
		Key    string
		List   []string
	}
	// Fenced rejects a request of Epoch, which is below the store's fence.
	Fenced struct{ Epoch, Fence uint64 }
	// Append asks a server to append Value to Key.
	Append struct {
		Seq        uint64
		Key, Value string
	}
	// Get asks a server for the list of Key.
	Get struct {
		Seq uint64
		Key string
	}
	// AppendOK confirms the Append Seq.
	AppendOK struct{ Seq uint64 }
	// GetOK answers the Get Seq.
	GetOK struct {
		Seq  uint64
		List []string
	}
	// NotLeader tells a client that the server does not serve requests now. Hint names the
	// server that the lock named last as the holder, or is empty.
	NotLeader struct {
		Seq  uint64
		Hint string
	}
)

func (m Acquire) Describe() string   { return "acquire" }
func (m Grant) Describe() string     { return "grant epoch=" + u(m.Epoch) + " ttl=" + m.TTL.String() }
func (m Busy) Describe() string      { return "busy holder=" + m.Holder }
func (m Sync) Describe() string      { return "sync epoch=" + u(m.Epoch) }
func (m SyncOK) Describe() string    { return "sync ok epoch=" + u(m.Epoch) }
func (m Fenced) Describe() string    { return "fenced epoch=" + u(m.Epoch) + " fence=" + u(m.Fence) }
func (m Get) Describe() string       { return "get #" + u(m.Seq) + " " + m.Key }
func (m AppendOK) Describe() string  { return "append ok #" + u(m.Seq) }
func (m GetOK) Describe() string     { return "get ok #" + u(m.Seq) + " len=" + strconv.Itoa(len(m.List)) }
func (m NotLeader) Describe() string { return "not leader #" + u(m.Seq) + " hint=" + m.Hint }
func (m Append) Describe() string    { return "append #" + u(m.Seq) + " " + m.Key + "+=" + m.Value }
func (m Write) Describe() string {
	return "write epoch=" + u(m.Epoch) + " " + m.Client + "#" + u(m.Seq) + " " + m.Key + "+=" + m.Value
}
func (m Written) Describe() string {
	return "written " + m.Client + "#" + u(m.Seq) + " " + m.Key + " len=" + strconv.Itoa(len(m.List))
}

func u(v uint64) string { return strconv.FormatUint(v, 10) }
package leasekv

import (
	"strconv"
	"time"

	"github.com/hmdsefi/faultline"
	"github.com/hmdsefi/faultline/check/history"
	"github.com/hmdsefi/faultline/kernel"
)

// Client runs operations one at a time until Stop, each on a random key of Keys: an append of a
// unique value, or a get. It sends a request again to the other server after Timeout without an
// answer, and after a NotLeader it waits Backoff and tries the hinted server or the other one. It
// waits up to Think between two operations.
type Client struct {
	W       *faultline.World
	Servers []kernel.NodeID
	Keys    []string
	Appends int       // percent of operations that are appends
	Stop    time.Time // no operation starts at or after Stop
	Timeout time.Duration
	Backoff time.Duration
	Think   time.Duration

	Started int  // operations started
	Done    []Op // completed operations, in completion order
}

// Op is a completed operation.
type Op struct {
	Client string
	Kind   string // "append" or "get"
	Key    string
	Value  string   // the appended value
	List   []string // the list a get returned
	Start  time.Time
	End    time.Time
}

// Boot starts the client's operations.
func (c *Client) Boot(n *kernel.Node) {
	c.Started, c.Done = 0, nil
	r := n.Rand()
	var (
		seq    uint64
		op     Op
		req    any
		id     int64
		active bool
		target = c.Servers[0]
		timer  kernel.EventID
	)
	var send func()
	send = func() {
		c.W.Net.Send(n, target, req)
		timer = n.After(c.Timeout, "timeout", func() {
			target = c.other(target)
			send()
		})
	}
	next := func() {
		if !n.Now().Before(c.Stop) {
			return
		}
		c.Started++
		seq++
		op = Op{Client: n.Name(), Key: c.Keys[r.IntN(len(c.Keys))], Start: n.Now()}
		if r.IntN(100) < c.Appends {
			op.Kind, op.Value = "append", n.Name()+"-"+strconv.FormatUint(seq, 10)
			req = Append{Seq: seq, Key: op.Key, Value: op.Value}
			id = c.W.History.Invoke(n.Name(), op.Kind, map[string]string{"key": op.Key, "value": op.Value})
		} else {
			op.Kind = "get"
			req = Get{Seq: seq, Key: op.Key}
			id = c.W.History.Invoke(n.Name(), op.Kind, map[string]string{"key": op.Key})
		}
		active = true
		send()
	}
	complete := func(list []string) {
		n.Cancel(timer)
		active = false
		op.List, op.End = list, n.Now()
		c.Done = append(c.Done, op)
		c.W.History.Complete(id, history.OK, list)
		n.After(kernel.Uniform(r, 0, c.Think), "next", next)
	}
	c.W.Net.Handle(n, func(from kernel.NodeID, msg any) {
		switch m := msg.(type) {
		case AppendOK:
			if active && m.Seq == seq {
				complete(nil)
			}
		case GetOK:
			if active && m.Seq == seq {
				complete(m.List)
			}
		case NotLeader:
			if !active || m.Seq != seq {
				return
			}
			n.Cancel(timer)
			target = c.other(from)
			if m.Hint != "" {
				if h := n.Sim().Lookup(m.Hint); h != nil {
					target = h.ID()
				}
			}
			timer = n.After(c.Backoff, "backoff", send)
		}
	})
	n.Post("next", next)
}

// other returns the server that is not s.
func (c *Client) other(s kernel.NodeID) kernel.NodeID {
	if s == c.Servers[0] {
		return c.Servers[1]
	}
	return c.Servers[0]
}

